package eu.arrowhead.port;

import java.time.*;
import java.util.*;
import static eu.arrowhead.port.Json.*;

final class MonitorStore {
 final Database db;MonitorStore(Database db)throws Exception{this.db=db;db.schema("PRAGMA journal_mode=WAL",
  "CREATE TABLE IF NOT EXISTS subscriptions(provider_system TEXT PRIMARY KEY,observation_types TEXT NOT NULL,enabled INTEGER NOT NULL,revision INTEGER NOT NULL,updated_at TEXT NOT NULL,updated_by TEXT)",
  "CREATE TABLE IF NOT EXISTS amqp_bindings(binding_key TEXT PRIMARY KEY)",
  "CREATE TABLE IF NOT EXISTS outbox(observation_id TEXT PRIMARY KEY,payload TEXT NOT NULL,mqtt_published INTEGER NOT NULL DEFAULT 0,attempts INTEGER NOT NULL DEFAULT 0,next_attempt REAL NOT NULL DEFAULT 0,last_error TEXT,created_at TEXT NOT NULL)",
  "CREATE TABLE IF NOT EXISTS observations(observation_id TEXT PRIMARY KEY,provider_system TEXT NOT NULL,service_instance TEXT NOT NULL,observation_type TEXT NOT NULL,source_time TEXT NOT NULL,source_epoch REAL NOT NULL,received_time TEXT NOT NULL,received_epoch REAL NOT NULL,quality TEXT,unit TEXT,payload TEXT NOT NULL)",
  "CREATE INDEX IF NOT EXISTS observations_by_system ON observations(provider_system,observation_type,source_epoch)","CREATE INDEX IF NOT EXISTS observations_by_age ON observations(received_epoch)",
  "CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT,at TEXT NOT NULL,actor TEXT NOT NULL,operation TEXT NOT NULL,target TEXT NOT NULL,outcome TEXT NOT NULL)");}
 static Map<String,Object>subscription(Map<String,Object>row){return m("providerSystem",row.get("provider_system"),"observationTypes",parse(str(row.get("observation_types"))),"enabled",integer(row.get("enabled"),0)!=0,"revision",row.get("revision"),"updatedAt",row.get("updated_at"),"updatedBy",row.get("updated_by"));}
 Map<String,Map<String,Object>>subscriptions()throws Exception{var out=new TreeMap<String,Map<String,Object>>();for(var row:db.query("SELECT * FROM subscriptions ORDER BY provider_system"))out.put(str(row.get("provider_system")),subscription(row));return out;}
 Map<String,Object>put(String provider,List<String>types,boolean enabled,String actor,Integer expected)throws Exception{
  if(!provider.matches("[A-Za-z][A-Za-z0-9_-]*"))throw new IllegalArgumentException("Valid providerSystem required");if(types.isEmpty()||types.stream().anyMatch(t->t.isBlank()||t.contains(".")||t.contains("#")||t.contains("/")||t.equals("*")&&!types.equals(List.of("*"))))throw new IllegalArgumentException("Valid observationTypes or [*] required");
  return db.transaction(c->{var rows=Database.query(c,"SELECT revision FROM subscriptions WHERE provider_system=?",provider);int revision=rows.isEmpty()?0:integer(rows.getFirst().get("revision"),0);if(expected!=null&&(rows.isEmpty()||expected!=revision))throw new Service.ApiError(409,"Subscription revision conflict");Database.update(c,"INSERT OR REPLACE INTO subscriptions VALUES(?,?,?,?,?,?)",provider,json(new TreeSet<>(types)),enabled?1:0,revision+1,now(),actor);return subscription(Database.query(c,"SELECT * FROM subscriptions WHERE provider_system=?",provider).getFirst());});
 }
 void audit(String actor,String operation,String target,String outcome)throws Exception{db.update("INSERT INTO audit(at,actor,operation,target,outcome)VALUES(?,?,?,?,?)",now(),actor,operation,target,outcome);}
 boolean enqueue(Map<String,Object>observation)throws Exception{return db.transaction(c->{String payload=json(observation);int changed=Database.update(c,"INSERT OR IGNORE INTO observations VALUES(?,?,?,?,?,?,?,?,?,?,?)",observation.get("observationId"),observation.get("providerSystem"),observation.get("serviceInstance"),observation.get("observationType"),observation.get("sourceTime"),epoch(str(observation.get("sourceTime"))),observation.get("receivedTime"),epoch(str(observation.get("receivedTime"))),observation.get("quality"),observation.get("unit"),payload);if(changed>0)Database.update(c,"INSERT OR IGNORE INTO outbox(observation_id,payload,created_at)VALUES(?,?,?)",observation.get("observationId"),payload,now());return changed>0;});}
 static double epoch(String time){return Instant.parse(time).toEpochMilli()/1000.0;}
 List<Map<String,Object>>pending()throws Exception{return db.query("SELECT * FROM outbox WHERE mqtt_published=0 AND next_attempt<=? ORDER BY created_at LIMIT 50",System.currentTimeMillis()/1000.0);}
 void published(String id)throws Exception{db.update("DELETE FROM outbox WHERE observation_id=?",id);}
 void failed(String id)throws Exception{db.update("UPDATE outbox SET last_error='MQTT publication failed',attempts=attempts+1,next_attempt=? WHERE observation_id=?",System.currentTimeMillis()/1000.0+5,id);}
 Map<String,Object>counts()throws Exception{return m("pending",db.query("SELECT count(*) AS n FROM outbox WHERE mqtt_published=0").getFirst().get("n"),"stored",db.query("SELECT count(*) AS n FROM observations").getFirst().get("n"));}
 int prune(double days)throws Exception{return db.update("DELETE FROM observations WHERE received_epoch<?",System.currentTimeMillis()/1000.0-days*86400);}
 List<Map<String,Object>>systems()throws Exception{return db.query("SELECT provider_system AS systemName,count(*)AS observationCount,min(source_time)AS firstObservationTime,max(source_time)AS lastObservationTime FROM observations GROUP BY provider_system ORDER BY provider_system");}
 List<Object>history(String system,List<String>types,Double from,Double to,int count)throws Exception{StringBuilder sql=new StringBuilder("SELECT payload FROM observations WHERE provider_system=?");var args=new ArrayList<Object>();args.add(system);if(!types.isEmpty()){sql.append(" AND observation_type IN (").append(String.join(",",Collections.nCopies(types.size(),"?"))).append(")");args.addAll(types);}if(from!=null){sql.append(" AND source_epoch>=?");args.add(from);}if(to!=null){sql.append(" AND source_epoch<=?");args.add(to);}sql.append(" ORDER BY source_epoch DESC LIMIT ?");args.add(count);return db.query(sql.toString(),args.toArray()).stream().map(row->parse(str(row.get("payload")))).toList();}
 Map<String,Object>latest(String system)throws Exception{var out=new TreeMap<String,Object>();for(var row:db.query("SELECT o.observation_type,o.payload FROM observations o JOIN(SELECT observation_type,max(source_epoch)AS latest FROM observations WHERE provider_system=? GROUP BY observation_type)m ON o.observation_type=m.observation_type AND o.source_epoch=m.latest WHERE o.provider_system=?",system,system))out.put(str(row.get("observation_type")),parse(str(row.get("payload"))));return out;}
 Set<String>bindings()throws Exception{var out=new TreeSet<String>();for(var row:db.query("SELECT binding_key FROM amqp_bindings"))out.add(str(row.get("binding_key")));return out;}
 void bindings(Set<String>bindings)throws Exception{db.transaction(c->{Database.update(c,"DELETE FROM amqp_bindings");for(String key:bindings)Database.update(c,"INSERT INTO amqp_bindings VALUES(?)",key);return null;});}
}
